{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required_symbols = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        parent = node.get("parent")
        if parent in children:
            children[parent].append(node["id"])

    removed = set()

    def active_subtree(node_id):
        result = []
        stack = [node_id]
        while stack:
            current = stack.pop()
            if current in removed or current not in by_id:
                continue
            result.append(current)
            stack.extend(children.get(current, ()))
        return result

    candidates = sorted(
        (node for node in nodes if node.get("removable") and node.get("utility", 0) < 0.3),
        key=lambda node: (-node.get("depth", 0), node["id"]),
    )

    for node in candidates:
        node_id = node["id"]
        if node_id in removed:
            continue
        subtree = active_subtree(node_id)
        if any(not by_id[current].get("removable", False) for current in subtree):
            continue
        proposed = set(subtree)
        remaining_symbols = {
            item.get("symbol")
            for item in nodes
            if item["id"] not in removed and item["id"] not in proposed
        }
        if required_symbols.issubset(remaining_symbols):
            removed.update(proposed)

    return {
        "removed_node_ids": [node["id"] for node in nodes if node["id"] in removed],
        "retained_node_ids": [node["id"] for node in nodes if node["id"] not in removed],
    }
"}
